function getParticipantsAccountIDsForDisplay(report: OnyxEntry<Report>, shouldExcludeHidden = false, shouldExcludeDeleted = false, shouldForceExcludeCurrentUser = false): number[] {
    if (isEmpty(report?.participants)) {
        return [];
    }
    const participantAccountIDs = Object.keys(report.participants).map(Number);

    if (shouldExcludeHidden) {
        const participants = report.participants;
        const visibleParticipantAccountIDs = Object.entries(participants)
            .filter(([, participant]) => !participant.hidden)
            .map(([accountID]) => Number(accountID));

        if (shouldForceExcludeCurrentUser) {
            const currentUserAccountID = SessionUtils.getAccountID();
            return visibleParticipantAccountIDs.filter((accountID) => accountID !== currentUserAccountID);
        }
        return visibleParticipantAccountIDs;
    }

    if (shouldForceExcludeCurrentUser) {
        const currentUserAccountID = SessionUtils.getAccountID();
        return participantAccountIDs.filter((accountID) => accountID !== currentUserAccountID);
    }

    return participantAccountIDs;

